def parse_json(s: str) -> object:
    """
    A simple recursive descent parser designed to convert a JSON string into corresponding Python objects.
    It handles strings (with escapes), numbers, booleans, null, arrays, and objects.
    """

    index = 0
    length = len(s)

    def skip_whitespace():
        nonlocal index
        while index < length and s[index].isspace():
            index += 1

    def parse_value():
        nonlocal index
        skip_whitespace()
        if index >= length:
            raise ValueError("Unexpected end of input")

        char = s[index]
        if char == '"':
            return parse_string()
        elif char.isdigit() or char == '-':
            return parse_number()
        elif char == 't':
            return parse_true()
        elif char == 'f':
            return parse_false()
        elif char == 'n':
            return parse_null()
        elif char == '[':
            return parse_array()
        elif char == '{':
            return parse_object()
        else:
            raise ValueError(f"Unexpected character: {char}")

    def parse_string():
        nonlocal index
        index += 1  # Skip initial quote
        start = index
        result = []
        while index < length:
            char = s[index]
            if char == '"':
                result.append(s[start:index])
                index += 1  # Skip final quote
                return ''.join(result)
            elif char == '\\':
                result.append(s[start:index])  # Add the part before the escape
                index += 1
                if index < length:
                    esc_char = s[index]
                    if esc_char in '"\\/bfnrt':
                        result.append(escapes[esc_char])
                    else:
                        raise ValueError(f"Invalid escape sequence: \\{esc_char}")
                start = index + 1
            index += 1
        raise ValueError("Unterminated string")

    def parse_number():
        nonlocal index
        start = index
        if s[index] == '-':
            index += 1
        while index < length and s[index].isdigit():
            index += 1
        if index < length and s[index] == '.':
            index += 1
            while index < length and s[index].isdigit():
                index += 1
        num = s[start:index]
        if '.' in num or 'e' in num or 'E' in num:
            return float(num)
        return int(num)

    def parse_true():
        nonlocal index
        if s[index:index + 4] == 'true':
            index += 4
            return True
        raise ValueError("Invalid token for true")

    def parse_false():
        nonlocal index
        if s[index:index + 5] == 'false':
            index += 5
            return False
        raise ValueError("Invalid token for false")

    def parse_null():
        nonlocal index
        if s[index:index + 4] == 'null':
            index += 4
            return None
        raise ValueError("Invalid token for null")

    def parse_array():
        nonlocal index
        index += 1  # Skip '['
        arr = []
        skip_whitespace()
        if s[index] == ']':
            index += 1  # Empty array case
            return arr
        while True:
            arr.append(parse_value())
            skip_whitespace()
            if s[index] == ']':
                index += 1
                return arr
            elif s[index] != ',':
                raise ValueError(f"Expected ',' or ']', got: {s[index]}")
            index += 1  # Skip ',' and continue

    def parse_object():
        nonlocal index
        index += 1  # Skip '{'
        obj = {}
        skip_whitespace()
        if s[index] == '}':
            index += 1  # Empty object case
            return obj
        while True:
            key = parse_string()
            skip_whitespace()
            if s[index] != ':':
                raise ValueError(f"Expected ':', got: {s[index]}")
            index += 1  # Skip ':'
            value = parse_value()
            obj[key] = value
            skip_whitespace()
            if s[index] == '}':
                index += 1
                return obj
            elif s[index] != ',':
                raise ValueError(f"Expected ',' or '}', got: {s[index]}")
            index += 1  # Skip ',' and continue

    escapes = {
        '"': '"',
        '\\': '\\',
        '/': '/',
        'b': '\b',
        'f': '\f',
        'n': '\n',
        'r': '\r',
        't': '\t'
    }

    return parse_value()

