    This parser uses a state machine approach to interpret JSON strings into Python objects.
    It processes the input string character by character, keeping track of the current state
    while building the data structure incrementally.
    """

    index = 0
    length = len(s)

    def advance():
        nonlocal index
        index += 1

    def current_char():
        return s[index] if index < length else None

    def skip_whitespace():
        while current_char() and current_char().isspace():
            advance()

    def parse_string():
        result = []
        advance()  # Skip the starting quote
        while current_char() is not None:
            if current_char() == '"':
                advance()  # Skip the ending quote
                return ''.join(result)
            elif current_char() == '\\':
                advance()  # Skip the escape character
                if current_char() == 'u':
                    # Unicode escape sequence
                    code = int(s[index+1:index+5], 16)
                    result.append(chr(code))
                    index += 5
                else:
                    es = {'"': '"', '\\': '\\', '/': '/', 'b': '\b', 'f': '\f', 'n': '\n', 'r': '\r', 't': '\t'}
                    result.append(es.get(current_char(), current_char()))
                    advance()
            else:
                result.append(current_char())
                advance()
        raise ValueError("Unterminated string")

    def parse_number():
        start = index
        if current_char() in ('-', '0') or current_char().isdigit():
            if current_char() == '0' and index + 1 < length and s[index + 1].isdigit():
                raise ValueError("Invalid number format")
            advance() if current_char() == '0' else None
            while current_char().isdigit():
                advance()
            if current_char() == '.':
                advance()
                if not current_char().isdigit():
                    raise ValueError("Invalid number format")
                while current_char() and current_char().isdigit():
                    advance()
            if current_char() in ('e', 'E'):
                advance()
                if current_char() in ('+', '-'):
                    advance()
                if not current_char().isdigit():
                    raise ValueError("Invalid number format")
                while current_char() and current_char().isdigit():
                    advance()
            return float(s[start:index]) if '.' in s[start:index] or 'e' in s[start:index] or 'E' in s[start:index] else int(s[start:index])
        raise ValueError("Invalid number format")

    def parse_value():
        skip_whitespace()
        if current_char() is None:
            raise ValueError("Unexpected end of input")
        char = current_char()
        if char == '"':
            return parse_string()
        elif char.isdigit() or char == '-':
            return parse_number()
        elif s.startswith('true', index):
            index += 4
            return True
        elif s.startswith('false', index):
            index += 5
            return False
        elif s.startswith('null', index):
            index += 4
            return None
        elif char == '[':
            return parse_array()
        elif char == '{':
            return parse_object()
        else:
            raise ValueError(f"Unexpected character: {char}")

    def parse_array():
        array = []
        advance()  # Skip '['
        skip_whitespace()
        if current_char() == ']':
            advance()  # Empty array
            return array
        while True:
            array.append(parse_value())
            skip_whitespace()
            if current_char() == ']':
                advance()
                return array
            elif current_char() != ',':
                raise ValueError(f"Expected ',' or ']', got: {current_char()}")
            advance()  # Skip ','

    def parse_object():
        obj = {}
        advance()  # Skip '{'
        skip_whitespace()
        if current_char() == '}':
            advance()  # Empty object
            return obj
        while True:
            key = parse_string()
            skip_whitespace()
            if current_char() != ':':
                raise ValueError(f"Expected ':', got: {current_char()}")
            advance()  # Skip ':'
            value = parse_value()
            obj[key] = value
            skip_whitespace()
            if current_char() == '}':
                advance()
                return obj
            elif current_char() != ',':
                raise ValueError(f"Expected ',' or '}', got: {current_char()}")
