def parse_json(s: str) -> object:
    """
    This parser employs a state machine approach to identify and convert JSON components 
    into their corresponding Python types. The parsing is done character by character 
    while maintaining a state to handle transitions between JSON structures effectively.
    """

    class StateMachine:
        def __init__(self, string):
            self.s = string
            self.len_s = len(string)
            self.index = 0
            self.state = self.parse_value

        def parse(self):
            while self.index < self.len_s:
                self.state()

        def parse_value(self):
            self.skip_whitespace()
            ch = self.next_char()
            if ch == '"':
                self.state = self.parse_string
            elif ch.isdigit() or (ch == '-' and self.peek_char().isdigit()):
                self.state = self.parse_number
            elif self.s.startswith('true', self.index):
                self.index += 4
                self.add_result(True)
            elif self.s.startswith('false', self.index):
                self.index += 5
                self.add_result(False)
            elif self.s.startswith('null', self.index):
                self.index += 4
                self.add_result(None)
            elif ch == '[':
                self.state = self.parse_array
            elif ch == '{':
                self.state = self.parse_object
            else:
                raise ValueError(f"Unexpected character: {ch}")

        def parse_string(self):
            self.index += 1  # skip opening quote
            result = []
            while self.index < self.len_s:
                ch = self.next_char()
                if ch == '"':
                    self.add_result(''.join(result))
                    self.state = self.parse_value
                    return
                elif ch == '\\':
                    esc_seq = self.next_char()
                    if esc_seq in '"\\/bfnrt':
                        result.append(self.handle_escape(esc_seq))
                    elif esc_seq == 'u':
                        unicode_value = self.s[self.index:self.index + 4]
                        result.append(chr(int(unicode_value, 16)))
                        self.index += 4
                else:
                    result.append(ch)

            raise ValueError("Unterminated string")

        def handle_escape(self, seq):
            return {
                '"': '"', '\\': '\\', '/': '/', 
                'b': '\b', 'f': '\f', 'n': '\n', 
                'r': '\r', 't': '\t'
            }[seq]

        def parse_number(self):
            start = self.index
            if self.next_char() == '-':
                ch = self.next_char()
            while self.index < self.len_s and self.peek_char().isdigit():
                self.index += 1
            if self.index < self.len_s and self.next_char() == '.':
                while self.index < self.len_s and self.peek_char().isdigit():
                    self.index += 1
            if self.index < self.len_s and self.peek_char() in 'eE':
                self.index += 1
                if self.peek_char() in '+-':
                    self.index += 1
                while self.index < self.len_s and self.peek_char().isdigit():
                    self.index += 1
            num_str = self.s[start:self.index]
            self.add_result(float(num_str) if '.' in num_str or 'e' in num_str or 'E' in num_str else int(num_str))

        def parse_array(self):
            self.index += 1  # skip '['
            self.add_result([])
            self.skip_whitespace()
            if self.peek_char() == ']':
                self.index += 1  # skip ']'
                self.state = self.parse_value
                return
            while True:
                self.state = self.parse_value
                self.skip_whitespace()
                if self.peek_char() == ']':
                    self.index += 1  # skip ']'
                    self.state = self.parse_value
                    return
                elif self.peek_char() == ',':
                    self.index += 1  # skip ','
                    self.skip_whitespace()
                else:
                    raise ValueError("Expected ',' or ']' in array")

        def parse_object(self):
            self.index += 1  # skip '{'
            self.add_result({})
            self.skip_whitespace()
            if self.peek_char() == '}':
                self.index += 1  # skip '}'
                self.state = self.parse_value
                return
            while True:
                key = self.string_value()
                self.skip_whitespace()
                if self.next_char() != ':':
                    raise ValueError("Expected ':' after key in object")
                self.state = self.parse_value
                value = self.results[-1]  # grab the last parsed value
                self.results[-1][key] = value  # assign value to the key
                self.skip_whitespace()
                if self.peek_char() == '}':
                    self.index += 1  # skip '}'
                    self.state = self.parse_value
                    return
                elif self.peek_char() == ',':
                    self.index += 1  # skip ','
                    self.skip_whitespace()
                else:
                    raise ValueError("Expected ',' or '}' in object")

        def skip_whitespace(self):
            while self.index < self.len_s and self.peek_char().isspace():
                self.index += 1

        def next_char(self):
            if self.index < self.len_s:
                ch = self.s[self.index]
                self.index += 1
                return ch
            return ''

        def peek_char(self):
            return self.s[self.index] if self.index < self.len_s else ''

        def add_result(self, value):
            if not hasattr(self, 'results'):
                self.results = []
            self.results.append(value)

        def string_value(self):
            self.skip_whitespace()
            if self.peek_char() == '"':
                self.state = self.parse_string
            return self.results.pop() if self.results else None

    sm = StateMachine(s)
    sm.parse()
    return sm.results[0] if sm.results else None

def parse_json(s: str) -> object:
    """
    This parser utilizes a recursive descent parsing technique to convert a JSON string 
    into corresponding Python objects. Each JSON construct is parsed through specific 
    functions that handle various data types such as strings, numbers, arrays, 
    objects, booleans, and null values.
    """

    index = 0

    def parse_value():
        nonlocal index
        skip_whitespace()
        if s[index] == '"':
            return parse_string()
        elif s[index] in '-0123456789':
            return parse_number()
        elif s.startswith('true', index):
            index += 4
            return True
        elif s.startswith('false', index):
            index += 5
            return False
        elif s.startswith('null', index):
            index += 4
            return None
        elif s[index] == '[':
            return parse_array()
        elif s[index] == '{':
            return parse_object()
        else:
            raise ValueError(f"Unexpected character: {s[index]}")

    def parse_string():
        nonlocal index
        index += 1  # skip the starting quote
        result = []
        while index < len(s):
            ch = s[index]
            if ch == '"':
                index += 1  # skip the ending quote
                return ''.join(result)
            elif ch == '\\':
                index += 1
                esc = s[index]
                if esc == 'u':
                    hex_value = s[index+1:index+5]
                    result.append(chr(int(hex_value, 16)))
                    index += 5
                else:
                    result.append(handle_escape(esc))
                    index += 1
            else:
                result.append(ch)
                index += 1
        raise ValueError("Unterminated string")

    def handle_escape(esc):
        return {
            '"': '"',
            '\\': '\\',
            '/': '/',
            'b': '\b',
            'f': '\f',
            'n': '\n',
            'r': '\r',
            't': '\t'
        }[esc]

    def parse_number():
        nonlocal index
        start = index
        if s[index] == '-':
            index += 1  # skip the minus sign
        while index < len(s) and s[index].isdigit():
            index += 1
        if index < len(s) and s[index] == '.':
            index += 1
            while index < len(s) and s[index].isdigit():
                index += 1
        if index < len(s) and s[index] in 'eE':
            index += 1
            if index < len(s) and s[index] in '+-':
                index += 1
            while index < len(s) and s[index].isdigit():
                index += 1
        num_str = s[start:index]
        return float(num_str) if '.' in num_str or 'e' in num_str else int(num_str)

    def parse_array():
        nonlocal index
        index += 1  # skip the opening bracket
        array = []
        skip_whitespace()
        if s[index] == ']':
            index += 1  # skip the closing bracket
            return array
        while True:
            array.append(parse_value())
            skip_whitespace()
            if s[index] == ']':
                index += 1  # skip the closing bracket
                break
            elif s[index] == ',':
                index += 1  # skip the comma
                skip_whitespace()
            else:
                raise ValueError("Expected ',' or ']' in array")

        return array

    def parse_object():
        nonlocal index
        index += 1  # skip the opening brace
        obj = {}
        skip_whitespace()
        if s[index] == '}':
            index += 1  # skip the closing brace
            return obj
        while True:
            key = parse_string()
            skip_whitespace()
            if s[index] != ':':
                raise ValueError("Expected ':' after key in object")
            index += 1  # skip the colon
            value = parse_value()
            obj[key] = value
            skip_whitespace()
            if s[index] == '}':
                index += 1  # skip the closing brace
                break
            elif s[index] == ',':
                index += 1  # skip the comma
                skip_whitespace()
            else:
                raise ValueError("Expected ',' or '}' in object")

        return obj

    def skip_whitespace():
        nonlocal index
        while index < len(s) and s[index].isspace():
            index += 1

    return parse_value()
